//! The parser of the grammar language.
//!
//! `generated.rs` is generated by prpr from `prpr.peg`, with the runtime inlined, so that changes
//! to the runtime never break it.

#[allow(clippy::all, dead_code, unused)]
#[rustfmt::skip]
mod generated;

use crate::ast::{Grammar, Span};
use crate::diag::Diagnostic;

pub fn parse(text: &str) -> Result<Grammar, Diagnostic> {
    generated::grammar(text).map_err(|e| {
        let span = e.span();
        Diagnostic::error(
            Span {
                start: span.start,
                end: span.end,
            },
            format!("syntax error: {e}"),
        )
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ast::*;

    fn parse_ok(s: &str) -> Grammar {
        match parse(s) {
            Ok(g) => g,
            Err(e) => panic!("{}", e.render(s, "<test>")),
        }
    }

    fn rules(g: &Grammar) -> Vec<&Rule> {
        g.items
            .iter()
            .filter_map(|it| match it {
                Item::Rule(r) => Some(r),
                Item::Rust(_) => None,
            })
            .collect()
    }

    #[test]
    fn rules_without_terminators() {
        let g = parse_ok("a = b c\nb: i64 = \"x\" { 1 }\npub atom c = [a-z]+ d:e?");
        let rs = rules(&g);
        assert_eq!(rs.len(), 3);
        assert_eq!(rs[0].name.name, "a");
        assert!(matches!(rs[0].body.kind, ExprKind::Seq(ref es) if es.len() == 2));
        assert_eq!(rs[1].name.name, "b");
        assert!(rs[1].ty.is_some());
        assert!(rs[2].atom && rs[2].vis.is_some());
    }

    #[test]
    fn items_after_rules_without_actions() {
        let s = "a = b\nmacro_rules! m { () => {} }\nb = c\nunion U { x: u8 }\nc = \"x\"";
        let g = parse_ok(s);
        assert_eq!(rules(&g).len(), 3);
        assert!(
            rules(&g)
                .iter()
                .all(|r| matches!(r.body.kind, ExprKind::Ref(_) | ExprKind::Lit(_)))
        );
    }

    #[test]
    fn rust_items() {
        let s = "use foo::{a, b};\n#[derive(Debug)]\nstruct S { x: [u8; 4] }\nconst X: S = S { x: [0; 4] };\nfn f() -> u8 { 0 }\nr = \"a\"";
        let g = parse_ok(s);
        let spans: Vec<&str> = g
            .items
            .iter()
            .filter_map(|it| match it {
                Item::Rust(sp) => Some(&s[*sp]),
                _ => None,
            })
            .collect();
        assert_eq!(
            spans,
            [
                "use foo::{a, b};",
                "#[derive(Debug)]\nstruct S { x: [u8; 4] }",
                "const X: S = S { x: [0; 4] };",
                "fn f() -> u8 { 0 }"
            ]
        );
    }

    #[test]
    fn types() {
        for ty in [
            "i64",
            "()",
            "Vec<(i64, String)>",
            "Vec<Vec<bool>>",
            "std::collections::BTreeMap<String, Vec<usize>>",
            "&'i str",
            "Box<dyn Fn(i32) -> &'static str>",
            "Box<dyn Iterator<Item = u8> + Send>",
            "[u8; 4]",
        ] {
            let s = format!("r: {ty} = \"a\"");
            let g = parse_ok(&s);
            assert_eq!(&s[rules(&g)[0].ty.unwrap()], ty);
        }
    }

    #[test]
    fn literals_and_classes() {
        let g = parse_ok(r#"r = "a\n\u{3042}" r"\d" '"' [^ '"' '\\' a-z '\0'-'\x1F' +-]"#);
        let ExprKind::Seq(es) = &rules(&g)[0].body.kind else {
            panic!()
        };
        assert!(matches!(&es[0].kind, ExprKind::Lit(Lit::Str(s)) if s == "a\n\u{3042}"));
        assert!(matches!(&es[1].kind, ExprKind::Lit(Lit::Str(s)) if s == "\\d"));
        assert!(matches!(&es[2].kind, ExprKind::Lit(Lit::Str(s)) if s == "\""));
        let ExprKind::Class(c) = &es[3].kind else {
            panic!()
        };
        assert!(c.negated);
        assert_eq!(
            c.ranges,
            [
                ('"', '"'),
                ('\\', '\\'),
                ('a', 'z'),
                ('\0', '\x1f'),
                ('+', '+'),
                ('-', '-')
            ]
        );
    }

    #[test]
    fn actions_and_operators() {
        let g = parse_ok(
            "r: i64 = x:a (b, \",\")* <c d> &e !f g+ { if x { 1 } else { \"}\".len() as i64 } } / &{ Some(0) }",
        );
        let ExprKind::Choice(alts) = &rules(&g)[0].body.kind else {
            panic!()
        };
        assert!(matches!(
            &alts[0].kind,
            ExprKind::Action { pred: false, .. }
        ));
        assert!(
            matches!(&alts[1].kind, ExprKind::Action { pred: true, expr, .. } if matches!(&expr.kind, ExprKind::Seq(es) if es.is_empty()))
        );
    }

    #[test]
    fn attributes() {
        let g = parse_ok(
            "#![input = bytes]\n/// Doc.\n#[label = \"number\"]\n#[memo]\natom num = [0-9]+",
        );
        assert_eq!(g.attrs.len(), 1);
        let r = rules(&g)[0];
        let names: Vec<&str> = r.attrs.iter().map(|a| a.name.name.as_str()).collect();
        assert_eq!(names, ["doc", "label", "memo"]);
    }

    #[test]
    fn errors() {
        let e = parse("r = (a b").unwrap_err();
        assert_eq!(e.span, prpr_runtime::span(8, 8));
        let e = parse("r = a / ").unwrap_err();
        assert_eq!(e.span, prpr_runtime::span(8, 8));
    }
}
